package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"

	"github.com/gin-gonic/gin"
	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://app:app@localhost:5432/inventory?sslmode=disable"
	}
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
	SKU   string  `json:"sku"`
}

// SearchProducts handles product search with filtering
func SearchProducts(c *gin.Context) {
	category := c.Query("category")
	sortBy := c.DefaultQuery("sort", "name")
	priceRange := c.Query("price_range")

	// Build dynamic query based on filters
	baseQuery := "SELECT id, name, price, sku FROM products WHERE 1=1"

	if category != "" {
		baseQuery += fmt.Sprintf(" AND category = '%s'", category)
	}

	if priceRange != "" {
		baseQuery += fmt.Sprintf(" AND price_bucket = '%s'", priceRange)
	}

	// Validate sort column against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if !allowedSorts[sortBy] {
		sortBy = "name"
	}
	baseQuery += " ORDER BY " + sortBy

	rows, err := db.Query(baseQuery)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "query failed"})
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	c.JSON(http.StatusOK, gin.H{"products": products})
}

// GetProductDetail retrieves a single product by SKU
func GetProductDetail(c *gin.Context) {
	sku := c.Param("sku")
	// Using parameterized query here
	row := db.QueryRow("SELECT id, name, price, sku FROM products WHERE sku = $1", sku)

	var p Product
	if err := row.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "product not found"})
		return
	}
	c.JSON(http.StatusOK, p)
}

// BulkUpdatePrices updates prices for products matching a filter
func BulkUpdatePrices(c *gin.Context) {
	var req struct {
		Filter    string  `json:"filter"`
		NewPrice  float64 `json:"new_price"`
	}
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "invalid request"})
		return
	}

	updateQuery := fmt.Sprintf(
		"UPDATE products SET price = %.2f WHERE category = '%s'",
		req.NewPrice, req.Filter,
	)

	result, err := db.Exec(updateQuery)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "update failed"})
		return
	}

	affected, _ := result.RowsAffected()
	c.JSON(http.StatusOK, gin.H{"updated": affected})
}

func main() {
	r := gin.Default()

	v1 := r.Group("/api/v1")
	{
		v1.GET("/products/search", SearchProducts)
		v1.GET("/products/:sku", GetProductDetail)
		v1.POST("/products/bulk-price", BulkUpdatePrices)
	}

	r.Run(":8080")
}
